@js:
var url;
if (/^\d+$/.test(key)) {
  // ID 模式
  url = baseUrl + "book/" + key + ".html";
} else if (/.*\.html$/.test(key)) {
  // HTML 模式
  url = baseUrl + "book/" + key;
} else if (/^[a-zA-Z][\u4e00-\u9fa5]+$/.test(key)) {
  // 单字母中文标签模式(如：a穿越,g穿越...)
  var cPart = key.substring(1);
  url = baseUrl + "newtag/" + encodeURIComponent(cPart) + "/" + page;
} else {
  // 默认搜索模式
  url = baseUrl + "search/" + key + "/" + page + ".html";
}
